import pandas as pd
import re

df = pd.read_csv("d:/Dataset Kaggle/fresh_october_2026_bugs.csv")

print("=== SCANNING 1,000 FRESH OCTOBER 2026 BUGS FOR SHOCKING DISCOVERIES ===")
print(f"Total baris data: {len(df)}")

# 1. Analisis AI-Generated PRs
ai_keywords = [
    "authored by an ai", "ai agent", "copilot", "claude", "gpt-4", "cursor", "coderabbit", "generated by", "autonomous"
]
pattern = "|".join(ai_keywords)

mask_desc = df["bug_description"].str.lower().str.contains(pattern, na=False)
mask_author = df["author"].str.lower().str.contains("bot|agent", na=False)
mask_title = df["title"].str.lower().str.contains(pattern, na=False)

ai_prs = df[mask_desc | mask_author | mask_title]
print(f"\n[TEMUAN SHOCKING 1: INVASI AI AGENT DI GITHUB OKTOBER 2026]")
print(f"Total PR yang secara terang-terangan dibuat/direview oleh AI Agent: {len(ai_prs)} / 1000 ({len(ai_prs)/len(df)*100:.1f}%)")

print("\n--- 5 Contoh PR Buatan AI Agent Nyata di Data Kita ---")
for idx, r in ai_prs.head(5).iterrows():
    repo = r["repo_name"]
    pr_num = r["pr_number"]
    author = r["author"]
    title = r["title"]
    desc = str(r["bug_description"]).replace("\n", " ")[:200]
    date = r["created_at"]
    print(f"\n[PR #{pr_num} di {repo}] (Tanggal: {date})")
    print(f"  Author : {author}")
    print(f"  Title  : {title}")
    print(f"  Snippet: {desc}...")

# 2. Temuan Bot Loop / Circular PRs
print("\n" + "=" * 65)
print("[TEMUAN SHOCKING 2: BOT MEMPERBAIKI KODE BUATAN BOT LAIN]")
bot_loop = df[df["author"].str.lower().str.contains("bot", na=False)]
print(f"Total PR yang dibuat akun Bot murni: {len(bot_loop)} repositori!")
print("Top Bot Authors:")
print(bot_loop["author"].value_counts().head(5))

# 3. Bug Paling Berbahaya / Kritis (Crash, Deadlock, Memory Leak, Security)
print("\n" + "=" * 65)
print("[TEMUAN SHOCKING 3: BUG KRITIS DI BULAN OKTOBER 2026]")
crit_keywords = ["crash", "deadlock", "memory leak", "infinite loop", "security", "vulnerability", "fatal"]
crit_mask = df["title"].str.lower().str.contains("|".join(crit_keywords), na=False) | df["bug_description"].str.lower().str.contains("|".join(crit_keywords), na=False)
crit_prs = df[crit_mask]
print(f"Total PR yang memperbaiki Bug Fatal / Deadlock / Crash: {len(crit_prs)} PR!")
for idx, r in crit_prs.head(4).iterrows():
    print(f"- [{r['created_at'][:10]}] {r['repo_name']}: {r['title']}")

